{"code":"def transform(grid):
    h=len(grid); w=len(grid[0])
    # The 1-colored figure is the reference vertical level; translate every
    # other colored figure so its top row matches that figure's top row.
    tops={}
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v:
                tops[v]=min(tops.get(v,h),r)
    ref=tops.get(1,0)
    out=[[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v:
                nr=r + ref-tops[v]
                if 0<=nr<h: out[nr][c]=v
    return out"}

